CREATE TABLE kp_moments(id TEXT PRIMARY KEY,kind TEXT NOT NULL CHECK(kind IN ('KP1','KP2')),title TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',position INTEGER NOT NULL,deleted_at BIGINT,updated_at BIGINT NOT NULL,updated_by TEXT NOT NULL);
CREATE TABLE kp_submoments(id TEXT PRIMARY KEY,moment_id TEXT NOT NULL REFERENCES kp_moments(id),title TEXT NOT NULL,position INTEGER NOT NULL,deleted_at BIGINT);
CREATE TABLE student_kp_assessments(student_id TEXT NOT NULL REFERENCES students(id) ON DELETE CASCADE,kind TEXT NOT NULL CHECK(kind IN ('KP1','KP2')),data JSONB NOT NULL,saved_data JSONB,is_draft BOOLEAN NOT NULL DEFAULT TRUE,revision INTEGER NOT NULL DEFAULT 0,updated_at BIGINT NOT NULL,updated_by TEXT NOT NULL,PRIMARY KEY(student_id,kind));
